mapper.select:
select goods.*, type.name as typeName, business.name as businessName
from goods
left join type on goods.type_id = type.id
left join business on goods.business_id = business.id

     and goods.id = #{id}
     and goods.name like concat('%', #{name}, '%')
     and goods.description = #{description}
     and goods.img = #{img}
     and goods.price = #{price}
     and goods.unit = #{unit}
     and goods.count = #{count}
     and goods.type_id = #{typeId}
     and goods.business_id = #{businessId}

order by goods.id desc
